#!/bin/bash
# Runs GenesisOutputs.t.sol (with the fixture generated by test.lua, path in $1) against the released Dave
# v3.0.0-alpha.7 cartesi-rollups/contracts build of the shared harness (bugs/harness/work/dave/released, with
# the regenerated step and cartesi-rollups-contracts 3.0.0-alpha.10), in a throw-away copy so the shared build
# is never touched. Prints forge's output. Exit 2 on setup errors, else 0 (test.lua reads the PASS/FAIL lines).
set -uo pipefail
HERE="$(cd "$(dirname "$0")" && pwd)"
FIXTURE="${1:?usage: dave.sh <GenesisOutputsFixture.sol>}"
D="${HARNESS_WORK:?source bugs/env.sh}/dave/released"
[ -f "$D/.built" ] && [ -d "$D/cartesi-rollups/contracts/out" ] && [ -d "$D/prt/contracts" ] &&
    [ -d "$D/machine/step/src" ] || {
    echo "dave.sh: released Dave build missing (bugs/harness/chain/build-dave.sh released)" >&2
    exit 2
}
command -v forge > /dev/null || { echo "dave.sh: forge not on PATH" >&2; exit 2; }
T="$(mktemp -d "${TMPDIR:-/tmp}/r8-goalepoch-2.XXXXXX")" || exit 2
trap 'rm -rf "$T"' EXIT
mkdir -p "$T/cartesi-rollups" "$T/prt" "$T/machine"
# Same relative layout as the build (foundry.toml: libs ../../prt/contracts/dependencies, prt-contracts/ and
# step/ remappings); the copied out/ and cache/ keep the compile incremental.
cp -a "$D/cartesi-rollups/contracts" "$T/cartesi-rollups/" && cp -a "$D/prt/contracts" "$T/prt/" &&
    cp -a "$D/machine/step" "$T/machine/" || exit 2
cp "$HERE/GenesisOutputs.t.sol" "$T/cartesi-rollups/contracts/test/" &&
    cp "$FIXTURE" "$T/cartesi-rollups/contracts/test/GenesisOutputsFixture.sol" || exit 2
cd "$T/cartesi-rollups/contracts" || exit 2
if [ "${SIMULATE_FIX:-}" = 1 ]; then
    # Self-check only (README): a stand-in for the fix, registering the template's outputs root in the
    # DaveConsensus constructor (here taken from the fixture; a real fix would prove it from the template hash
    # with a machine validity proof), to show that the test then exits 0.
    sed -i 's|^import {IDaveConsensus} from "./IDaveConsensus.sol";|&\nimport {GenesisOutputsFixture} from "../test/GenesisOutputsFixture.sol";|;
            s|^        emit EpochSealed(0, 0, inputIndexUpperBound, initialMachineStateHash, bytes32(0), tournament);|        _outputsMerkleRoots[GenesisOutputsFixture.OUTPUTS_MERKLE_ROOT] = true;\n&|' src/DaveConsensus.sol
    grep -q '^import {GenesisOutputsFixture}' src/DaveConsensus.sol &&
        grep -q GenesisOutputsFixture.OUTPUTS_MERKLE_ROOT src/DaveConsensus.sol || { echo "SIMULATE_FIX patch failed" >&2; exit 2; }
fi
forge test --offline --match-contract GenesisOutputsAuditTest -vv 2>&1
exit 0
